const body = $input.first().json.body || $input.first().json;
const name  = (body.customer_name  || '').trim();
const email = (body.customer_email || '').trim().toLowerCase();
const phone = (body.customer_phone || '').trim();
if (!name)  throw new Error('customer_name is required');
if (!phone) throw new Error('customer_phone is required');
return [{ json: {
  customer_name:  name,
  customer_email: email,
  customer_phone: phone,
  request_id:     body.request_id     || '',
  room_id:        body.room_id        || '',
  room_name:      body.room_name      || '',
  booking_date:   body.booking_date   || '',
  date_from:      body.date_from      || body.booking_date || '',
  date_to:        body.date_to        || body.booking_date || '',
  start_time:     body.start_time     || '',
  end_time:       body.end_time       || '',
  guest_count:    body.guest_count    || '',
  event_type:     body.event_type     || '',
  notes:          body.notes          || '',
  total_amount:   body.total_amount   || 0,
  payment_amount: body.payment_amount || 0,
  payment_type:   body.payment_type   || 'deposit',
  payment_method: body.payment_method || 'cash',
  status:         body.status         || 'booked',
  booking_source: 'walk_in',
  tenant_id: parseInt(body.tenant_id || $input.first().json.headers?.['x-tenant-id'] || $input.first().json.query?.tenant_id || '0')
}}];

const mbResult = $input.first().json;
const payload = $('Build Full Payload').first().json;
// make-booking returns status:'success' on success, status:'error'/'blocked' on failure
const ok = mbResult.status === 'success' || mbResult.message === 'Booking secured.';
return [{ json: {
  success: ok,
  message: ok ? (mbResult.message || 'Walk-in booking created') : (mbResult.message || 'Booking failed'),
  customer_id: payload.customer_id,
  is_new:      payload.is_new
}}];

